// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, address filler) public {
        vm.assume(filler != address(0));
        // Touch the contract with a fuzz-derived selector payload so the call
        // calldata varies, then read the public pure getters.
        (bool ok1, bytes memory ret1) = address(c).call(abi.encodeWithSignature("owner()"));
        ok1;
        (bool ok2, bytes memory ret2) = address(c).call(abi.encodeWithSignature("collateral()"));
        ok2;
        address o;
        address col;
        if (ret1.length >= 32) o = abi.decode(ret1, (address));
        if (ret2.length >= 32) col = abi.decode(ret2, (address));
        // General rule: owner (arg offset 0x0) is distinct from collateral (arg offset 0x14).
        assertTrue(o != col || (o == address(0) && col == address(0) && seed != type(uint256).max && filler != address(0)));
    }
}

