pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(bytes32 payload) public {
        // Build a call to owner() with appended immutable-args-style tail.
        // Calldata = selector(4) + word(payload) + word(uint16 lenTag) => total 68 bytes.
        // _getImmutableArgsOffset = calldatasize - (last2bytes + 2) = 68 - (66 + 2) = 0,
        // so both versions read starting at calldata offset 0.
        // Reference: shr(0x60, word@0) — word@0 is the selector, upper 20 bytes are zero
        //            => owner() MUST be address(0) for every payload.
        // Mutant reads word@0x28 = bytes 40..71, which lie inside our fuzzed tail
        //            => returns nonzero for (most) payload values.
        bytes memory data = abi.encodePacked(
            c.owner.selector,
            abi.encode(payload, uint16(66))
        );

        (bool ok, bytes memory ret) = address(c).call(data);
        address returned;
        if (ok && ret.length >= 32) {
            returned = abi.decode(ret, (address));
        }

        assertTrue(ok && returned == address(0));
    }
}

