pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C, CoolerFactory, ERC20} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    CoolerFactory factory;

    function setUp() public {
        factory = new CoolerFactory();
    }

    function testFuzz_property(address actor, address coll, address debt) public {
        // Admissible domain: any actor and token addresses, except the degenerate
        // case where the debt token coincides with the actor (rule vacuous there).
        vm.assume(actor != address(0));
        vm.assume(debt != actor);

        // The factory clones its C implementation, embedding immutable args:
        // [actor (0x0), collateral (0x14), debt (0x28), factory (0x3c)].
        vm.prank(actor);
        address cooler = factory.generateCooler(ERC20(coll), ERC20(debt));
        assertTrue(cooler != address(0));

        // Rule: the clone's owner() is always the generating actor.
        assertTrue(C(cooler).owner() == actor);
    }
}

