pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed, uint256 w1) public {
        // keep seed in the low 48 bits so that word2 = (seed << 16) | 66 has
        // bytes 8..27 equal to zero (where the mutant's +0x28 read lands)
        seed = bound(seed, 0, 2**48 - 1);
        w1 = bound(w1, 0, 2**256 - 1);

        // calldata: owner() selector + two 32-byte words; trailer (last two
        // bytes) = 0x0042 (66) so _getImmutableArgsOffset() = 68 - (66+2) = 0
        uint256 w2 = (seed << 16) | 66;
        bytes memory data = abi.encodePacked(c.owner.selector, w1, w2);

        // expected: the 20 bytes at the derived offset 0, i.e. data[0..19]
        address expected;
        assembly {
            expected := shr(96, mload(add(data, 32)))
        }
        // the selector's leading bytes guarantee expected != address(0)
        vm.assume(expected != address(0));

        (bool ok, bytes memory ret) = address(c).call(data);
        assertTrue(ok);

        address returned;
        assembly {
            returned := shr(96, mload(add(ret, 32)))
        }
        // general rule: owner() returns the immutable-arg word at the
        // trailer-computed offset; the mutant reads offset 0x28 instead and
        // returns the zero bytes of word2, breaking equality
        assertTrue(returned == expected);
    }
}

