pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 embedded) public {
        // Keep the top 20 bytes of the embedded word nonzero so the correct
        // return value is a distinguishable, well-defined address.
        vm.assume(embedded >= uint256(uint160(1)) << 96);

        // Build calldata for owner(): selector + one 32-byte word + a two-byte
        // trailer of 0x0020. calldatasize = 4 + 32 + 2 = 38, so the immutable
        // args offset computed from the trailer is 38 - 34 = 4, pointing exactly
        // at the embedded word.
        bytes memory cd = abi.encodePacked(
            c.owner.selector,
            embedded,
            uint16(0x0020)
        );

        (bool ok, bytes memory ret) = address(c).call(cd);
        assertTrue(ok, "owner() call failed");

        address got = abi.decode(ret, (address));
        address expected = address(uint160(embedded >> 96));

        // Reference rule: owner() always returns the top 20 bytes of the word
        // the trailer offset points to. The mutant reads 0x28 further, past the
        // end of calldata (out-of-range loads are zero), so it returns 0 here.
        assertTrue(got == expected, "owner() must return embedded top-20-bytes");
    }
}

