// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address owner, address factory) public {
        // Keep params in admissible domain (wide): owner and factory must differ,
        // factory must be non-zero so the arg is a meaningful address.
        vm.assume(owner != factory);
        vm.assume(factory != address(0));

        // Build a minimal clone of the deployed implementation c, appending the
        // immutable args exactly like CoolerFactory.generateCooler does:
        // (owner @0x0, collateral @0x14, debt @0x28, factory @0x3c).
        bytes memory data = abi.encodePacked(owner, address(0), address(0), factory);
        uint256 extraLength = data.length + 2;
        uint256 creationSize = 0x41 + extraLength;
        uint256 runSize = creationSize - 10;

        bytes memory payload = abi.encodePacked(
            hex"61", bytes2(uint16(runSize)),
            hex"3d81600a3d39f33d3d3d3d363d3d37", bytes2(uint16(extraLength)),
            hex"603736393661", bytes2(uint16(extraLength)),
            hex"013d73", address(c),
            hex"5af43d3d93803e603557fd5bf3",
            data,
            bytes2(uint16(uint16(data.length)))
        );

        address cloneAddr;
        assembly {
            cloneAddr := create(0, add(payload, 32), mload(payload))
        }

        // General rule: owner() returns the first immutable arg (the owner),
        // never the factory address stored at offset 0x3c.
        assertTrue(
            cloneAddr != address(0) && C(cloneAddr).owner() == owner,
            "owner() must return the immutable arg at offset 0x0"
        );
    }
}
